37	class Plugin {
38		/**
39		 * Container instance.
40		 *
41		 * @var Container
42		 */
43		private $container;
44	
45		/**
46		 * Is the plugin loaded
47		 *
48		 * @var boolean
49		 */
50		private $loaded = false;
51	
52		/**
53		 * Plugin file path.
54		 *
55		 * @var string
56		 */
57		private $plugin_path;
58	
59		/**
60		 * Job IDs.
61		 *
62		 * These constants are used to identify the wp_options storing the different types of backup jobs.
63		 */
64		public const FILES_JOB_ID    = 'backwpup_backup_files_job_id';
65		public const DATABASE_JOB_ID = 'backwpup_backup_database_job_id';
66		public const FIRST_JOB_ID    = 'backwpup_first_backup_job_id';
67	
68		/**
69		 * Instantiate the class.
70		 *
71		 * @param Container $container Instance of the container.
72		 * @param string    $plugin_path Path to the plugin file.
73		 */
74		public function __construct( Container $container, string $plugin_path ) {
75			$this->container   = $container;
76			$this->plugin_path = $plugin_path;
77	
78			add_filter( 'backwpup_container', [ $this, 'get_container' ] );
79		}
80	
81		/**
82		 * Returns the container instance.
83		 *
84		 * @return Container
85		 */
86		public function get_container() {
87			return $this->container;
88		}
89	
90		/**
91		 * Checks if the plugin is loaded
92		 *
93		 * @return boolean
94		 */
95		private function is_loaded(): bool {
96			return $this->loaded;
97		}
98	
99		/**
100		 * Plugin init.
101		 *
102		 * @return void
103		 */
104		public function init(): void {
105			if ( $this->is_loaded() ) {
106				return;
107			}
108	
109			// Nothing else matters if we're not on the main site.
110			if ( ! is_main_network() && ! is_main_site() ) {
111				return;
112			}
113	
114			BackWPup::set_is_pro( file_exists( dirname( BACKWPUP_PLUGIN_FILE ) . '/inc/Pro/class-pro.php' ) );
115	
116			// Start upgrade if needed.
117			if (
118				get_site_option( 'backwpup_version' ) !== BackWPup::get_plugin_data( 'Version' )
119				||
120				! wp_next_scheduled( 'backwpup_check_cleanup' )
121			) {
122				add_action( 'init', [ BackWPup_Install::class, 'activate' ], 0 );
123			}
124	
125			$plugin_data = [
126				'version'    => BackWPup::get_plugin_data( 'version' ),
127				'pluginName' => 'backwpup-pro/backwpup.php',
128				'slug'       => 'backwpup',
129			];
130	
131			// Register the third party services.
132			BackWPup_ThirdParties::register();
133	
134			$this->container->addShared(
135				'event_manager',
136				function () {
137					return new EventManager();
138				}
139			);
140	
141			$plugin_path = dirname( BACKWPUP_PLUGIN_FILE ) . '/views';
142			$this->container->add( 'template_path', new StringArgument( $plugin_path ) );
143	
144			$this->container->add( 'options_api', Options::class )
145				->addArgument( new StringArgument( 'backwpup_' ) );
146	
147			// Load service providers.
148			$providers = require dirname( BACKWPUP_PLUGIN_FILE ) . '/config/providers.php';
149	
150			foreach ( $providers as $service_provider ) {
151				$provider_instance = new $service_provider();
152				$this->container->addServiceProvider( $provider_instance );
153	
154				// Load each service provider's subscribers if found.
155				$this->load_subscribers( $provider_instance );
156			}
157	
158			// Load pro features.
159			if ( BackWPup::is_pro() ) {
160				/**
161				 * WpOptionsLicenseRepository instance.
162				 *
163				 * @var WpOptionsLicenseRepository $license_repository
164				 */
165				$license_repository = $this->container->get( 'license_repository' );
166				$instance_key       = $license_repository->get_instance_key();
167				$instance_key       = '' !== $instance_key ? $instance_key : wp_generate_password( 12, false );
168	
169				$license = new License(
170					$license_repository->get_product_id(),
171					$license_repository->get_api_key(),
172					$instance_key,
173					$license_repository->get_status()
174				);
175	
176				$plugin_update      = new PluginUpdate( $license, $plugin_data );
177				$plugin_information = new PluginInformation( $license, $plugin_data );
178	
179				$pro = new BackWPup_Pro( $plugin_update, $plugin_information );
180				$pro->init();
181			}
182	
183			// Only in backend.
184			$this->load_admin_backend( $plugin_data );
185	
186			// WP-Cron.
187			if ( wp_doing_cron() ) {
188				if ( ! empty( $_GET['backwpup_run'] ) && class_exists( BackWPup_Job::class ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
189					// Early disable caches.
190					BackWPup_Job::disable_caches();
191					// Add action for running jobs in wp-cron.php.
192					add_action( 'wp_loaded', [ BackWPup_Cron::class, 'cron_active' ], PHP_INT_MAX );
193					// For external-link (runext) job starts, the request comes from an outside
194					// cron service without a BackWPup auth cookie.  Pre-authenticate the
195					// configured user now (before the init hook) so that mu-plugins that
196					// restrict wp-cron.php to a specific user do not block the request.
197					BackWPup_Cron::preauth_for_external_run();
198				} else {
199					// Add cron actions.
200					add_action( 'backwpup_cron', [ BackWPup_Cron::class, 'run' ] );
201					add_action( 'backwpup_check_cleanup', [ BackWPup_Cron::class, 'check_cleanup' ] );
202				}
203	
204				// If in cron the rest is not needed.
205				return;
206			}
207	
208			// Inject the configured user's auth cookie into WordPress's own spawn_cron()
209			// loopback so that mu-plugins restricting wp-cron.php to a specific user do
210			// not block scheduled BackWPup jobs.
211			add_filter( 'cron_request', [ BackWPup_Cron::class, 'authenticate_cron_request' ] );
212	
213			$this->loaded = true;
214		}
