216		/**
217		 * Load admin related
218		 *
219		 * @param array $plugin_data Plugin data.
220		 *
221		 * @return void
222		 */
223		private function load_admin_backend( array $plugin_data ): void {
224			// Bail early.
225			if ( ! is_admin() && class_exists( BackWPup_Admin::class ) ) {
226				return;
227			}
228	
229			$settings_views     = [];
230			$settings_updaters  = [];
231			$license_repository = null;
232	
233			if ( BackWPup::is_pro() ) {
234				$activate        = new LicenseActivation( $plugin_data );
235				$deactivate      = new LicenseDeactivation( $plugin_data );
236				$status          = new LicenseStatusRequest();
237				$license_manager = $this->container->get( 'license_manager' );
238	
239				$settings_views     = array_merge(
240					$settings_views,
241					[
242						new EncryptionSettingsView(),
243						new LicenseSettingsView(
244							$activate,
245							$deactivate,
246							$status
247						),
248					]
249				);
250				$settings_updaters  = array_merge(
251					$settings_updaters,
252					[
253						new EncryptionSettingUpdater(),
254						new LicenseSettingUpdater(
255							$activate,
256							$deactivate,
257							$status,
258							$license_manager
259						),
260					]
261				);
262				$license_repository = $this->container->get( 'license_repository' );
263			}
264	
265			$settings = new BackWPup_Page_Settings(
266				$settings_views,
267				$settings_updaters,
268				$license_repository
269			);
270	
271			$admin = new BackWPup_Admin( $settings );
272			$admin->init();
273	
274			/**
275			 * Filter whether BackWPup will show the plugins in the admin bar or not.
276			 *
277			 * @param bool $is_in_admin_bar Whether the admin link will be shown in the admin bar or not.
278			 */
279			$is_in_admin_bar = wpm_apply_filters_typed( 'boolean', 'backwpup_is_in_admin_bar', (bool) get_site_option( 'backwpup_cfg_showadminbar' ) );
280	
281			if ( true === $is_in_admin_bar ) {
282				$admin_bar = new BackWPup_Adminbar( $admin );
283				add_action( 'init', [ $admin_bar, 'init' ] );
284			}
285		}
286	
287		/**
288		 * Load list of event subscribers from service provider.
289		 *
290		 * @param ServiceProviderInterface $service_provider Instance of service provider.
291		 *
292		 * @return void
293		 */
294		private function load_subscribers( ServiceProviderInterface $service_provider ): void {
295			if ( empty( $service_provider->get_subscribers() ) ) {
296				return;
297			}
298	
299			foreach ( $service_provider->get_subscribers() as $subscriber ) {
300				$subscriber_object = $this->container->get( $subscriber );
301	
302				if ( $subscriber_object instanceof SubscriberInterface ) {
303					$this->container->get( 'event_manager' )->add_subscriber( $subscriber_object );
304				}
305			}
306		}
307	}
